assert len(P) == 40, f"total {len(P)}"
assert len([p for p in P if p["case_id"] in [f"LY-{n}" for n in range(537,544)] + [f"LY-{n}" for n in range(601,614)]]) == 20, "B16 count"
ids = [p["case_id"] for p in P]; assert len(set(ids)) == 40
for p in P:
    assert p["prediction_text"] and p["basis"] and 0 <= p["confidence"] <= 1
    t = p["trigger"]; assert set(t) == {"changed_main", "reserve_used", "disputed", "reason"}
    (OUT / (p["case_id"] + ".json")).write_text(json.dumps(p, ensure_ascii=False, indent=1), encoding="utf-8")
for p in P:
    q = json.loads((OUT / (p["case_id"] + ".json")).read_text(encoding="utf-8"))
    assert q["case_id"] == p["case_id"] and "第八节功量核" in q["basis"] and "主线认定" in q["basis"]
cm = sum(p["trigger"]["changed_main"] for p in P); ru = sum(p["trigger"]["reserve_used"] for p in P); di = sum(p["trigger"]["disputed"] for p in P)
print(f"WROTE {len(P)} changed_main={cm} reserve_used={ru} disputed={di}")
